import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, PlaneGeometry, BoxGeometry, Group, Mesh, PointLight, DirectionalLight, AmbientLight } from 'three/webgpu';
import { uv, smoothstep, mix, color as nColor, texture, vec2, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const palette = {
    bg: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  const root = new THREE.Group();

  // --- Backdrop: vertical gradient + vignette (no flat void) ---
  const backdropGeo = new THREE.PlaneGeometry(7.2, 6);
  const uvs = uv();
  const grad = mix(nColor(palette.bg), nColor(palette.surface), smoothstep(0, 1, uvs.y));
  const vign = smoothstep(1.5, 0.45, length(uvs.sub(0.5).mul(vec2(1.0, 0.72))));
  const backdropNode = mix(nColor('#000000'), grad, vign.mul(0.75).add(0.25));
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: backdropNode });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);

  // --- Local lighting ---
  const key = new THREE.DirectionalLight(new THREE.Color(palette.paper), 1.2);
  key.position.set(4.5, 5, 6);
  root.add(key);

  const rim = new THREE.DirectionalLight(new THREE.Color(palette.accent), 0.8);
  rim.position.set(-5, 1.5, 3);
  root.add(rim);

  const fill = new THREE.PointLight(new THREE.Color('#c9c9c3'), 0.7);
  fill.position.set(0, 0, 4);
  root.add(fill);

  const localAmbient = new THREE.AmbientLight(new THREE.Color('#3a3842'), 0.35);
  root.add(localAmbient);

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline') ?? items[0] ?? { text: 'Inside the atelier' };
  const captionItems = items.filter(i => i.role === 'caption').length
    ? items.filter(i => i.role === 'caption')
    : items.slice(1);

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 0.34,
    color: palette.paper,
    align: 'left'
  });
  headline.position.set(-1.6, 1.65, 0.2);
  root.add(headline);

  const captionLabels = ['DIAL ROOM', 'ESCAPEMENT BENCH', 'CNC HALL', 'FINISHING LAB', 'ARCHIVE VAULT', 'ASSEMBLY LINE ONE'];
  const captions = [];
  for (let i = 0; i < 6; i++) {
    const item = captionItems[i] ?? { text: captionLabels[i] };
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 0.09,
      color: palette.paper,
      align: 'right',
      letterSpacingPx: 1.5
    });
    txt.position.set(-1.6, 0, 0.25);
    txt.visible = false;
    txt.traverse(m => {
      if (m.material) {
        m.material.transparent = true;
        m.material.opacity = 0;
        m.material.depthWrite = false;
      }
    });
    root.add(txt);
    captions.push({ obj: txt, state: { opacity: 0 } });
  }

  // --- Loop column of plates ---
  const column = new THREE.Group();
  column.position.set(0.9, 0, 0);
  root.add(column);

  const W = 1.9;
  const H = 1.2;
  const PITCH = 1.5;
  const LOOP = 9.0;

  const frameMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(palette.ink),
    roughness: 0.5,
    metalness: 0.5,
    clearcoat: 0.1
  });

  const accentMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(palette.accent),
    emissive: new THREE.Color(palette.accent),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.1
  });

  const tints = [
    new THREE.Color('#e8ecf2'),
    new THREE.Color('#efece6'),
    new THREE.Color('#d9e2e8'),
    new THREE.Color('#e8e2d9'),
    new THREE.Color('#d8d4cf'),
    new THREE.Color('#e2e2dc')
  ];

  const plates = [];
  for (let i = 0; i < 6; i++) {
    const plate = new THREE.Group();

    const frame = new THREE.Mesh(new THREE.BoxGeometry(W + 0.06, H + 0.06, 0.04), frameMat);
    plate.add(frame);

    const edgeHighlight = new THREE.Mesh(
      new THREE.BoxGeometry(W + 0.08, 0.02, 0.05),
      new MeshStandardNodeMaterial({
        color: new THREE.Color('#2a2a33'),
        roughness: 0.45,
        metalness: 0.55,
        clearcoat: 0.1
      })
    );
    edgeHighlight.position.set(0, (H + 0.06) / 2 + 0.01, 0.03);
    plate.add(edgeHighlight);

    const photoMat = new MeshStandardNodeMaterial({
      color: new THREE.Color('#5a544d'),
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1
    });

    const u = uv();
    const fbBase = mix(nColor('#2a272e'), nColor('#4a463f'), smoothstep(0, 1, u.y));
    const fbVig = smoothstep(1.2, 0.4, length(u.sub(0.5).mul(vec2(1.92, 1.2))));
    photoMat.colorNode = fbBase.mul(fbVig);

    const photo = new THREE.Mesh(new THREE.PlaneGeometry(W, H), photoMat);
    photo.position.z = 0.025;
    plate.add(photo);
